stimulus.text:
DBA : GRANT SELECT, INSERT, DELETE ON R TO U1;
DBA : GRANT SELECT ON R TO U2 WITH GRANT OPTION;
U2  : GRANT SELECT ON R TO U3;
DBA : REVOKE DELETE ON R FROM U1;

-- (ㄱ)
SELECT COUNT(*) FROM CUST CROSS JOIN GRADE;

-- (ㄴ)
SELECT COUNT(*) FROM CUST A
INNER JOIN GRADE B ON A.AMOUNT BETWEEN B.MIN_AMT AND B.MAX_AMT;

-- (ㄷ)
SELECT COUNT(*) FROM CUST A
FULL OUTER JOIN GRADE B ON A.AMOUNT BETWEEN B.MIN_AMT AND B.MAX_AMT;

SELECT COUNT(*)
FROM (
SELECT DISTINCT A, B
FROM Tbl_A
WHERE C IN (
SELECT D
FROM Tbl_B
WHERE UPPER(E) = 'E'
)
) X;

CREATE TABLE T1 (
COL1 NUMBER,
COL2 NUMBER,
CONSTRAINT CK_T1 CHECK (COL1 > 10 AND COL2 > 5)
);

CREATE VIEW V1 AS
SELECT DEPTNO, SUM(SAL) AS SS
FROM EMP GROUP BY DEPTNO;

create table t1 (no number);
insert into t1 values (1);
insert into t1 values (2);
savepoint sv1;
update t1 set no=4 where no=1;
savepoint sv1;
delete from t1 where no >= 2;
rollback to sv1;
insert into t1 values(3);
commit;
select max(no) from t1;

CREATE TABLE T1 (
COL1 NUMBER DEFAULT 9 PRIMARY KEY,
COL2 VARCHAR2(10) NOT NULL
);
